cases.source:
permit (principal, action == App::Action::"read", resource) when { context.count > 3 };
forbid (principal, action == App::Action::"write", resource);
permit (principal, action == App::Action::"read", resource) when { context.count < 0 };

expect.cedarPolicyText:
permit(principal, action == App::Action::"read", resource) when { !((context.count) <= 3) };
forbid(principal, action == App::Action::"write", resource) when { true };
permit(principal, action == App::Action::"read", resource) when { (context.count) < 0 };

